{"name":"Canal Ray","author":"1001 Homebrew Spells Forum Thread","level":2,"school":"Evocation","classes":["Sorcerer","Wizard"],"effects":["Buff","Warding","Utility"],"castingTime":"1 Action","range":"30 ft","duration":"Instantaneous","area":"None","concentration":false,"ritual":false,"damageSpell":true,"verbal":true,"somatic":true,"material":false,"materialText":"","materialType":"None","materialCost":0,"attackSave":"None","diceValue":"4d6","avgRoll":14,"targets":0,"upcastable":false,"upcastText":"","hasRestriction":true,"restrictionText":"","description":"You blast your enemies with rays of acidic energy. You may fire one ray, plus one additional ray for every four levels beyond 3rd (to a maximum of three rays at 11th level). Each ray requires a ranged touch attack to hit and deals 4d6 points of acid damage.

